/*
    Ecommerce Dataset
    Converted from the supplied MySQL script for Microsoft SQL Server / SSMS.

    Notes:
    - Creates database Ecommerce_DB if it does not already exist.
    - Recreates the six dataset tables in the dbo schema.
    - Preserves the source primary-key values using IDENTITY_INSERT.
    - Splits multi-row INSERTs into batches of at most 1,000 rows.
    - Run this entire script in SSMS. Keep SQLCMD Mode disabled.
*/

IF DB_ID(N'Ecommerce_DB') IS NULL
BEGIN
    CREATE DATABASE Ecommerce_DB;
END;
GO

USE Ecommerce_DB;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

-- Rebuild the dataset tables so the script can be run again without duplicate rows.
IF OBJECT_ID(N'dbo.order_item_refunds', N'U') IS NOT NULL DROP TABLE dbo.order_item_refunds;
IF OBJECT_ID(N'dbo.order_items', N'U') IS NOT NULL DROP TABLE dbo.order_items;
IF OBJECT_ID(N'dbo.orders', N'U') IS NOT NULL DROP TABLE dbo.orders;
IF OBJECT_ID(N'dbo.products', N'U') IS NOT NULL DROP TABLE dbo.products;
IF OBJECT_ID(N'dbo.website_pageviews', N'U') IS NOT NULL DROP TABLE dbo.website_pageviews;
IF OBJECT_ID(N'dbo.website_sessions', N'U') IS NOT NULL DROP TABLE dbo.website_sessions;
GO


-- Create dbo.website_sessions
CREATE TABLE dbo.website_sessions (
    website_session_id BIGINT IDENTITY(1,1) NOT NULL,
    created_at DATETIME2(0) NOT NULL,
    user_id BIGINT NOT NULL,
    is_repeat_session SMALLINT NOT NULL,
    utm_source VARCHAR(12) NULL,
    utm_campaign VARCHAR(20) NULL,
    utm_content VARCHAR(15) NULL,
    device_type VARCHAR(15) NULL,
    http_referer VARCHAR(30) NULL,
    CONSTRAINT PK_website_sessions PRIMARY KEY CLUSTERED (website_session_id)
);
CREATE NONCLUSTERED INDEX IX_website_sessions_user_id ON dbo.website_sessions(user_id);
GO

-- Load 472,871 rows into dbo.website_sessions in batches of at most 1,000.
SET IDENTITY_INSERT dbo.website_sessions ON;
GO
